contracts/user/UserRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.13;

contract UserRegistry {
    enum Role {
        None,
        Patient,
        Doctor
    }

    mapping(address => Role) public roles;
    event Registered(address indexed user, Role role);

    function registerAsPatient() public {
        require(roles[msg.sender] == Role.None, "Already registered");
        roles[msg.sender] = Role.Patient;
        emit Registered(msg.sender, Role.Patient);
    }

    function registerAsDoctor() public {
        require(roles[msg.sender] == Role.None, "Already registered");
        roles[msg.sender] = Role.Doctor;
        emit Registered(msg.sender, Role.Doctor);
    }

    function isPatient(address user) external  view returns (bool) {
        return roles[user] == Role.Patient;
    }

    function isDoctor(address user) external  view returns (bool) {
        return roles[user] == Role.Doctor;
    }
}

contracts/permission/PermissionControl.s.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.13;
import "contracts/user/UserRegistry.sol";

contract PermissionControl is UserRegistry {
    mapping(address => mapping(address => bool)) internal permissions;

    modifier onlyDoctor() {
        require(roles[msg.sender] == Role.Doctor, "Only doctor allowed");
        _;
    }

    modifier onlyPatient() {
        require(roles[msg.sender] == Role.Patient, "Only patient allowed");
        _;
    }

    function checkPermission(address _patient, address _doctor)
        public
        view
        returns (bool)
    {
        return permissions[_patient][_doctor];
    }
}

